def is_palindrome(s):
    return s == s[::-1]

def count_insertions_to_palindrome(s):
    n = len(s)
    count = 0
    for i in range(n + 1):
        new_s = s[:i] + 'a' + s[i:]
        if is_palindrome(new_s):
            count += 1
    return count

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    T = int(data[0])
    index = 1
    results = []

    for _ in range(T):
        S = data[index]
        index += 1
        result = count_insertions_to_palindrome(S)
        results.append(result)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
